import assert from 'node:assert/strict';import {GameEngineXBridge} from './bridge.mjs';import {SwarmKlein} from '../klein_bridge.js';
const k=new SwarmKlein();let saved=0;const b=new GameEngineXBridge({swarm:()=>({units:[{address:{gate:1}},{address:{gate:1}},{address:{gate:64}},{address:{gate:3},latent:true}]}),klein:()=>k,onLearn:()=>saved++});
assert.deepEqual(b.sync().gates,[1,64]);assert.equal(b.scene.elements.length,2);assert.equal(b.scene.elements[1].sequence,'GGG');const old=b.sim.getState().position.x;const r=b.step('move',{learn:true});assert.ok(r.position.x>old);assert.ok(r.learned);assert.equal(k.events,1);assert.equal(saved,1);assert.ok(k.canLeadTo('gamex:move','gamex:simulation'));assert.equal(b.step('rest').learned,false);assert.equal(k.events,1);assert.ok(b.oracle('test').bestAction);assert.throws(()=>b.step('invalid'));b.reset();assert.equal(b.events.length,0);console.log('13 bridge assertions passed');